public class Main {

    static boolean isArmstrong(int number) {
        int digits = String.valueOf(number).length();
        int sum = 0;
        int temp = number;

        while (temp > 0) {
            int digit = temp % 10;
            sum += (int) Math.pow(digit, digits);
            temp /= 10;
        }
        return sum == number;
    }

    public static void main(String[] args) {
        int[] numbers = {153, 9474, 123};
        for (int n : numbers) {
            System.out.println(n + (isArmstrong(n) ? " is an Armstrong number" : " is not an Armstrong number"));
        }
    }
}

public class Main {

    static boolean isPalindrome(int number) {
        if (number < 0) {
            return false;
        }
        int original = number;
        int reverse = 0;

        while (number > 0) {
            reverse = reverse * 10 + number % 10;
            number /= 10;
        }
        return original == reverse;
    }

    public static void main(String[] args) {
        int[] numbers = {121, 123, 1331, -121};
        for (int n : numbers) {
            System.out.println(n + " -> " + isPalindrome(n));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        String text = "Selenium";

        // 1. Loop with StringBuilder
        StringBuilder reversed = new StringBuilder();
        for (int i = text.length() - 1; i >= 0; i--) {
            reversed.append(text.charAt(i));
        }
        System.out.println("Loop: " + reversed);

        // 2. Two pointers on a char array
        char[] chars = text.toCharArray();
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left++] = chars[right];
            chars[right--] = temp;
        }
        System.out.println("Two pointers: " + new String(chars));

        // 3. Built-in
        System.out.println("Built-in: " + new StringBuilder(text).reverse());
    }
}

