import java.util.Arrays;

public class Main {

    static boolean isAnagramBySorting(String first, String second) {
        char[] a = first.replaceAll("\\s+", "").toLowerCase().toCharArray();
        char[] b = second.replaceAll("\\s+", "").toLowerCase().toCharArray();
        if (a.length != b.length) {
            return false;
        }
        Arrays.sort(a);
        Arrays.sort(b);
        return Arrays.equals(a, b);
    }

    static boolean isAnagramByCounting(String first, String second) {
        String a = first.replaceAll("\\s+", "").toLowerCase();
        String b = second.replaceAll("\\s+", "").toLowerCase();
        if (a.length() != b.length()) {
            return false;
        }
        int[] counts = new int[26];
        for (int i = 0; i < a.length(); i++) {
            counts[a.charAt(i) - 'a']++;
            counts[b.charAt(i) - 'a']--;
        }
        for (int count : counts) {
            if (count != 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("listen / silent: " + isAnagramBySorting("listen", "silent"));
        System.out.println("Dormitory / Dirty room: " + isAnagramByCounting("Dormitory", "Dirty room"));
        System.out.println("hello / world: " + isAnagramByCounting("hello", "world"));
    }
}

