import java.util.Set;
import java.util.TreeSet;

public class Main {

    static void permute(String prefix, String remaining) {
        if (remaining.isEmpty()) {
            System.out.println(prefix);
            return;
        }
        for (int i = 0; i < remaining.length(); i++) {
            String rest = remaining.substring(0, i) + remaining.substring(i + 1);
            permute(prefix + remaining.charAt(i), rest);
        }
    }

    static void uniquePermutations(String prefix, String remaining, Set<String> results) {
        if (remaining.isEmpty()) {
            results.add(prefix);
            return;
        }
        for (int i = 0; i < remaining.length(); i++) {
            uniquePermutations(prefix + remaining.charAt(i),
                    remaining.substring(0, i) + remaining.substring(i + 1), results);
        }
    }

    public static void main(String[] args) {
        permute("", "ABC");

        Set<String> unique = new TreeSet<>();
        uniquePermutations("", "AAB", unique);
        System.out.println("Unique permutations of AAB: " + unique);
    }
}

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Integer[] first = {1, 2, 3, 4, 5, 3};
        Integer[] second = {3, 4, 5, 6, 7};

        // Approach 1: nested loops, O(n * m)
        System.out.print("Nested loops:");
        for (int i = 0; i < first.length; i++) {
            for (int j = 0; j < second.length; j++) {
                if (first[i].equals(second[j])) {
                    System.out.print(" " + first[i]);
                    break;
                }
            }
        }
        System.out.println();

        // Approach 2: Set, O(n + m), no duplicates
        Set<Integer> lookup = new LinkedHashSet<>(Arrays.asList(first));
        Set<Integer> common = new LinkedHashSet<>();
        for (Integer value : second) {
            if (lookup.contains(value)) {
                common.add(value);
            }
        }
        System.out.println("Using a Set: " + common);

        // Approach 3: retainAll
        Set<Integer> result = new LinkedHashSet<>(Arrays.asList(first));
        result.retainAll(Arrays.asList(second));
        System.out.println("Using retainAll: " + result);
    }
}

import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] numbers = {5, 2, 8, 1, 3};
        System.out.println("Before: " + Arrays.toString(numbers));

        for (int i = 0; i < numbers.length - 1; i++) {
            boolean swapped = false;

            for (int j = 0; j < numbers.length - 1 - i; j++) {
                if (numbers[j] > numbers[j + 1]) {
                    int temp = numbers[j];
                    numbers[j] = numbers[j + 1];
                    numbers[j + 1] = temp;
                    swapped = true;
                }
            }

            System.out.println("After pass " + (i + 1) + ": " + Arrays.toString(numbers));
            if (!swapped) {
                break;      // already sorted
            }
        }

        System.out.println("Sorted: " + Arrays.toString(numbers));
    }
}

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        int[] numbers = {4, 1, 2, 4, 3, 1, 5, 2};

        // 1. LinkedHashSet: keeps first-seen order
        Set<Integer> unique = new LinkedHashSet<>();
        for (int number : numbers) {
            unique.add(number);
        }
        System.out.println("LinkedHashSet: " + unique);

        // 2. Streams
        int[] distinct = Arrays.stream(numbers).distinct().toArray();
        System.out.println("Stream distinct: " + Arrays.toString(distinct));

        // 3. Without collections: sort, then two indexes
        int[] sorted = numbers.clone();
        Arrays.sort(sorted);
        int last = 0;
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] != sorted[last]) {
                sorted[++last] = sorted[i];
            }
        }
        System.out.println("In place after sorting: " + Arrays.toString(Arrays.copyOf(sorted, last + 1)));
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        // One missing number in 1..5: sum formula
        int[] single = {1, 2, 4, 5};
        int n = 5;
        int expectedSum = n * (n + 1) / 2;
        int actualSum = 0;
        for (int value : single) {
            actualSum += value;
        }
        System.out.println("Single missing number: " + (expectedSum - actualSum));

        // Several missing numbers in 1..10: mark what is present
        int[] multiple = {1, 2, 4, 6, 7, 10};
        int max = 10;
        boolean[] present = new boolean[max + 1];
        for (int value : multiple) {
            present[value] = true;
        }

        List<Integer> missing = new ArrayList<>();
        for (int i = 1; i <= max; i++) {
            if (!present[i]) {
                missing.add(i);
            }
        }
        System.out.println("Multiple missing numbers: " + missing);
    }
}

