import java.util.Arrays;

public class Main {

    static int linearSearch(int[] array, int target) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == target) {
                return i;
            }
        }
        return -1;
    }

    static int binarySearch(int[] sorted, int target) {
        int low = 0;
        int high = sorted.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (sorted[mid] == target) {
                return mid;
            } else if (sorted[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] numbers = {40, 10, 50, 20, 30};
        System.out.println("Linear search for 50: index " + linearSearch(numbers, 50));

        Arrays.sort(numbers);
        System.out.println("Sorted: " + Arrays.toString(numbers));
        System.out.println("Binary search for 40: index " + binarySearch(numbers, 40));
        System.out.println("Binary search for 35: index " + binarySearch(numbers, 35));
        System.out.println("Built-in binarySearch for 20: index " + Arrays.binarySearch(numbers, 20));
    }
}

import java.util.Arrays;

