import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {

    // Comparable: natural order is by id
    static class Employee implements Comparable<Employee> {
        final int id;
        final String name;
        final double salary;

        Employee(int id, String name, double salary) {
            this.id = id;
            this.name = name;
            this.salary = salary;
        }

        String getName() { return name; }
        double getSalary() { return salary; }

        @Override
        public int compareTo(Employee other) {
            return Integer.compare(this.id, other.id);
        }

        @Override
        public String toString() { return id + "-" + name + "-" + (int) salary; }
    }

    public static void main(String[] args) {
        List<Employee> employees = new ArrayList<>();
        employees.add(new Employee(3, "Ravi", 50000));
        employees.add(new Employee(1, "Meena", 70000));
        employees.add(new Employee(2, "Asha", 60000));

        Collections.sort(employees);                                   // Comparable
        System.out.println("By id (Comparable): " + employees);

        employees.sort(Comparator.comparing(Employee::getName));       // Comparator
        System.out.println("By name (Comparator): " + employees);

        employees.sort(Comparator.comparingDouble(Employee::getSalary).reversed());
        System.out.println("By salary, descending: " + employees);
    }
}

