import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> tools = new ArrayList<>(Arrays.asList("Java", "Selenium", "TestNG", "Maven"));

        // 1. Enhanced for loop
        for (String tool : tools) {
            System.out.print(tool + " ");
        }
        System.out.println();

        // 2. Indexed loop
        for (int i = 0; i < tools.size(); i++) {
            System.out.print(i + "=" + tools.get(i) + " ");
        }
        System.out.println();

        // 3. forEach with a lambda
        tools.forEach(tool -> System.out.print(tool.toUpperCase() + " "));
        System.out.println();

        // Removing inside for-each fails
        try {
            for (String tool : tools) {
                if (tool.startsWith("S")) {
                    tools.remove(tool);
                }
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("ConcurrentModificationException in for-each");
        }

        // 4. Iterator: safe removal
        Iterator<String> iterator = tools.iterator();
        while (iterator.hasNext()) {
            if (iterator.next().startsWith("T")) {
                iterator.remove();
            }
        }
        System.out.println("After iterator.remove(): " + tools);

        // 5. removeIf
        tools.removeIf(tool -> tool.startsWith("M"));
        System.out.println("After removeIf: " + tools);
    }
}

