        }

        // 2. keySet
        System.out.println("Keys: " + marks.keySet());

        // 3. values
        int total = 0;
        for (int value : marks.values()) {
            total += value;
        }
        System.out.println("Total: " + total);

        // 4. forEach with a lambda
        marks.forEach((subject, mark) -> System.out.println(subject + " = " + mark));

        // 5. Iterator: safe removal while iterating
        Iterator<Map.Entry<String, Integer>> iterator = marks.entrySet().iterator();
        while (iterator.hasNext()) {
            if (iterator.next().getValue() < 50) {
                iterator.remove();
            }
        }
        System.out.println("After removing marks below 50: " + marks);
    }
}

