import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class Main {

    static class Employee {
        final int id;
        final String name;

        Employee(int id, String name) {
            this.id = id;
            this.name = name;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Employee)) return false;
            Employee other = (Employee) o;
            return id == other.id && name.equals(other.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, name);
        }
    }

    public static void main(String[] args) {
        // Collision: different keys, same hash code
        System.out.println("hashCode of Aa: " + "Aa".hashCode() + ", of BB: " + "BB".hashCode());

        Map<String, Integer> map = new HashMap<>();
        map.put("Aa", 1);
        map.put("BB", 2);          // same bucket, different key: both kept
        map.put("Aa", 10);         // same key: value replaced
        System.out.println("Aa -> " + map.get("Aa") + ", BB -> " + map.get("BB") + ", size " + map.size());

        // Custom key needs equals() and hashCode()
        Map<Employee, String> roles = new HashMap<>();
        roles.put(new Employee(1, "Asha"), "Tester");
        System.out.println("Lookup with an equal key: " + roles.get(new Employee(1, "Asha")));
    }
}

public class Main {

