            countPage();
            System.out.println("Firefox opens " + url);
        }
    }

    public static void main(String[] args) {
        // Polymorphism: one reference type, different behaviour
        Browser[] browsers = {new Chrome(), new Firefox()};
        for (Browser browser : browsers) {
            browser.open("https://example.com");
        }

        Chrome chrome = new Chrome();
        chrome.open("https://example.com/a");
        chrome.open("https://example.com/b");
        System.out.println("Pages opened by this Chrome: " + chrome.getPagesOpened());
    }
}

