import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Integer> numbers = Arrays.asList(10, 25, 30, 45, 50);

        Predicate<Integer> isAbove20 = n -> n > 20;            // T -> boolean
        Function<Integer, String> toLabel = n -> "N" + n;      // T -> R
        Consumer<String> printer = s -> System.out.println("Consumed: " + s);   // T -> void
        Supplier<String> message = () -> "Supplied value";      // () -> T

        List<String> labels = numbers.stream()
                .filter(isAbove20)        // Predicate
                .map(toLabel)             // Function
                .collect(Collectors.toList());
        System.out.println("filter + map: " + labels);

        labels.stream().limit(2).forEach(printer);              // Consumer

        int sum = numbers.stream().reduce(0, (a, b) -> a + b);  // BinaryOperator
        System.out.println("reduce sum: " + sum);

        List<Integer> descending = numbers.stream()
                .sorted((a, b) -> b - a)                         // Comparator
                .collect(Collectors.toList());
        System.out.println("sorted descending: " + descending);

        System.out.println(message.get());
    }
}

