        int[] stable = new int[original.length];
        int index = 0;
        for (int value : original) {
            if (value % 2 == 0) {
                stable[index++] = value;
            }
        }
        for (int value : original) {
            if (value % 2 != 0) {
                stable[index++] = value;
            }
        }
        System.out.println("Extra array (order kept): " + Arrays.toString(stable));

        // Approach 2: two pointers, in place, O(n) time and O(1) space
        int[] arr = original.clone();
        int left = 0;
        int right = arr.length - 1;

        while (left < right) {
            while (left < right && arr[left] % 2 == 0) {
                left++;
            }
            while (left < right && arr[right] % 2 != 0) {
                right--;
            }
            if (left < right) {
                int temp = arr[left];
                arr[left] = arr[right];
                arr[right] = temp;
                left++;
                right--;
            }
        }
        System.out.println("Two pointers (in place): " + Arrays.toString(arr));
    }
}

