public class Main {

    static class Wait {
        private final int seconds;
        private final int pollMillis;

        // Constructor overloading: different ways to create the object
        Wait() {
            this(10, 500);
        }

        Wait(int seconds) {
            this(seconds, 500);
        }

        Wait(int seconds, int pollMillis) {
            this.seconds = seconds;
            this.pollMillis = pollMillis;
        }

        // Method overloading: same operation, different inputs
        String until(String condition) {
            return "Waiting " + seconds + "s for " + condition;
        }

        String until(String condition, String message) {
            return until(condition) + " (" + message + ")";
        }

        String describe() {
            return seconds + "s, poll " + pollMillis + "ms";
        }
    }

    public static void main(String[] args) {
        System.out.println(new Wait().describe());
        System.out.println(new Wait(30).describe());
        System.out.println(new Wait(30, 200).describe());

        Wait wait = new Wait(5);
        System.out.println(wait.until("visibility"));
        System.out.println(wait.until("visibility", "login button"));
    }
}

