import java.util.ArrayList;
import java.util.List;

public class Main {

    static void addItem(List<String> list) {
        list.add("added inside method");      // changes the same object
    }

    static void reassign(List<String> list) {
        list = new ArrayList<>();             // only the local copy of the reference changes
        list.add("lost");
    }

    public static void main(String[] args) {
        List<String> first = new ArrayList<>();
        List<String> second = first;          // two references, one object

        second.add("hello");
        System.out.println("first sees: " + first);
        System.out.println("Same object: " + (first == second));

        addItem(first);
        System.out.println("After addItem: " + first);

        reassign(first);
        System.out.println("After reassign: " + first);

        List<String> nothing = null;
        try {
            nothing.size();
        } catch (NullPointerException e) {
            System.out.println("null reference -> NullPointerException");
        }
    }
}

public class Main {

    static int depth = 0;

    static void recurse() {
        depth++;
        recurse();                  // never stops: fills the stack
    }

    public static void main(String[] args) {
        Runtime runtime = Runtime.getRuntime();
        System.out.println("Max heap is available: " + (runtime.maxMemory() > 0));

        String first = new String("temporary");   // object on the heap
        String second = first;                    // two references
        first = null;                             // still reachable through 'second'
        System.out.println("Still reachable: " + second);
        second = null;                            // now eligible for garbage collection
        System.gc();                              // a request, not a command
        System.out.println("Object is now eligible for GC");

        try {
            recurse();
        } catch (StackOverflowError e) {
            System.out.println("StackOverflowError after deep recursion: " + (depth > 1000));
        }
    }
}

