import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

public class Main {

    static class Product {
        private final int id;
        private final String name;

        Product(int id, String name) {
            this.id = id;
            this.name = name;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }
            Product other = (Product) o;
            return id == other.id && Objects.equals(name, other.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, name);
        }
    }

    public static void main(String[] args) {
        Product fromUi = new Product(10, "Backpack");
        Product fromApi = new Product(10, "Backpack");
        Product other = new Product(11, "Bike Light");

        System.out.println("Same reference: " + (fromUi == fromApi));
        System.out.println("equals(): " + fromUi.equals(fromApi));
        System.out.println("Same hashCode: " + (fromUi.hashCode() == fromApi.hashCode()));
        System.out.println("Different product equals: " + fromUi.equals(other));

        Set<Product> products = new HashSet<>();
        products.add(fromUi);
        products.add(fromApi);          // treated as a duplicate
        products.add(other);
        System.out.println("Set size: " + products.size());
    }
}

