public class Main {

    interface Clickable {
        void click();

        default String describe() {
            return "can be clicked";
        }
    }

    interface Typeable {
        void type(String text);

        default String describe() {
            return "can receive text";
        }
    }

    // One class, two interfaces: multiple inheritance of type
    static class SearchBox implements Clickable, Typeable {
        @Override
        public void click() {
            System.out.println("Search box clicked");
        }

        @Override
        public void type(String text) {
            System.out.println("Typed: " + text);
        }

        // Both interfaces have describe(): the class must resolve the conflict
        @Override
        public String describe() {
            return Clickable.super.describe() + " and " + Typeable.super.describe();
        }
    }

    public static void main(String[] args) {
        SearchBox box = new SearchBox();
        box.click();
        box.type("selenium");
        System.out.println("Search box " + box.describe());

        Clickable asClickable = box;       // the same object seen through each type
        Typeable asTypeable = box;
        asClickable.click();
        asTypeable.type("java");
    }
}

public class Main {

    interface TestEvents {                      // 4 methods
        void onStart();
        void onPass();
        void onFail();
        void onSkip();
    }

    interface SuiteEvents {                     // 2 methods
        void onSuiteStart();
        void onSuiteFinish();
    }

    // 1. Adapter: empty bodies for everything
    static abstract class EventAdapter implements TestEvents, SuiteEvents {
        public void onStart() { }
        public void onPass() { }
        public void onFail() { }
        public void onSkip() { }
        public void onSuiteStart() { }
        public void onSuiteFinish() { }
    }

    // Override only what is needed: 2 of the 6 methods
    static class FailureListener extends EventAdapter {
        @Override
        public void onFail() {
            System.out.println("Adapter approach: screenshot on failure");
        }

        @Override
        public void onSuiteFinish() {
            System.out.println("Adapter approach: send the report");
        }
    }

    // 3. Default methods in the interface itself
    interface ModernEvents {
        default void onPass() { }
        default void onFail() { }
        default void onSkip() { }
    }

    static class ModernListener implements ModernEvents {
        @Override
        public void onFail() {
            System.out.println("Default-method approach: only onFail overridden");
        }
    }

    public static void main(String[] args) {
        FailureListener listener = new FailureListener();
        listener.onStart();          // inherited empty body: does nothing
        listener.onFail();
        listener.onSuiteFinish();

        ModernListener modern = new ModernListener();
        modern.onPass();             // default body: does nothing
        modern.onFail();
    }
}

public class Main {

    // Abstraction
    static abstract class Account {
        private final String accountNumber;      // Encapsulation: private state
        private double balance;

        Account(String accountNumber, double openingBalance) {
            this.accountNumber = accountNumber;
            this.balance = openingBalance;
        }

        public void deposit(double amount) {
