        }

        public void withdraw(double amount) {
            if (amount <= 0 || amount > availableToWithdraw()) {
                throw new IllegalArgumentException("Withdrawal of " + amount + " not allowed");
            }
            balance -= amount;
        }

        protected double availableToWithdraw() {
            return balance;
        }

        public double getBalance() { return balance; }
        public String getAccountNumber() { return accountNumber; }

        public abstract double calculateInterest();
    }

    // Inheritance
    static class SavingsAccount extends Account {
        private static final double MIN_BALANCE = 1000;
        private static final double RATE = 0.04;

        SavingsAccount(String number, double balance) { super(number, balance); }

        @Override
        protected double availableToWithdraw() {
            return getBalance() - MIN_BALANCE;
        }

        @Override
        public double calculateInterest() { return getBalance() * RATE; }
    }

    static class CurrentAccount extends Account {
        private static final double OVERDRAFT = 5000;

        CurrentAccount(String number, double balance) { super(number, balance); }

        @Override
        protected double availableToWithdraw() {
            return getBalance() + OVERDRAFT;
        }

        @Override
        public double calculateInterest() { return 0; }
    }

    public static void main(String[] args) {
        Account[] accounts = {
                new SavingsAccount("SB-101", 10000),
                new CurrentAccount("CA-201", 2000)
        };

        accounts[0].deposit(5000, "salary");
        accounts[0].withdraw(3000);
        accounts[1].withdraw(6000);             // allowed by the overdraft

        // Run-time polymorphism
        for (Account account : accounts) {
            System.out.println(account.getAccountNumber() + " balance " + account.getBalance()
                    + ", interest " + account.calculateInterest());
        }

        try {
            accounts[0].withdraw(11500);        // would break the minimum balance
        } catch (IllegalArgumentException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
    }
}

public class Main {

    // Double-checked locking
    static class ReportManager {
        private static volatile ReportManager instance;
        private static int created = 0;

        private ReportManager() {
            created++;
        }

        static ReportManager getInstance() {
            if (instance == null) {                         // first check, no lock
                synchronized (ReportManager.class) {
                    if (instance == null) {                 // second check, inside the lock
                        instance = new ReportManager();
                    }
                }
            }
            return instance;
        }

        static int timesCreated() { return created; }
    }

    // Holder idiom: lazy and thread-safe without locks
    static class Config {
        private Config() { }

        private static class Holder {
            static final Config INSTANCE = new Config();
        }

        static Config getInstance() { return Holder.INSTANCE; }
    }

    // Enum singleton
    enum Logger {
        INSTANCE;

        void log(String message) { System.out.println("LOG: " + message); }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread[] threads = new Thread[20];
        for (int i = 0; i < threads.length; i++) {
            threads[i] = new Thread(ReportManager::getInstance);
            threads[i].start();
        }
        for (Thread thread : threads) {
            thread.join();
        }

        System.out.println("Instances created by 20 threads: " + ReportManager.timesCreated());
        System.out.println("Holder returns the same object: " + (Config.getInstance() == Config.getInstance()));
        Logger.INSTANCE.log("enum singleton works");
    }
}

