import java.io.FileNotFoundException;
import java.io.IOException;

public class Main {

    static void printParents(Class<?> type) {
        StringBuilder chain = new StringBuilder(type.getSimpleName());
        Class<?> parent = type.getSuperclass();
        while (parent != null) {
            chain.append(" -> ").append(parent.getSimpleName());
            parent = parent.getSuperclass();
        }
        System.out.println(chain);
    }

    public static void main(String[] args) {
        printParents(FileNotFoundException.class);        // checked
        printParents(NullPointerException.class);         // unchecked
        printParents(NumberFormatException.class);        // unchecked
        printParents(StackOverflowError.class);           // error

        Throwable checked = new IOException("disk problem");
        Throwable unchecked = new ArithmeticException("divide by zero");
        System.out.println("IOException is unchecked? " + (checked instanceof RuntimeException));
        System.out.println("ArithmeticException is unchecked? " + (unchecked instanceof RuntimeException));
    }
}

public class Main {

    static void recurse(int depth) {
        recurse(depth + 1);
    }

    public static void main(String[] args) {
        // Exception: recoverable, handled and the program continues
        try {
            String text = null;
            text.length();
        } catch (NullPointerException e) {
            System.out.println("Exception handled: " + e.getClass().getSimpleName());
        }

        // Error: a JVM-level problem (caught here only to demonstrate it)
        try {
            recurse(1);
        } catch (StackOverflowError e) {
            System.out.println("Error occurred: " + e.getClass().getSimpleName());
        }

        // AssertionError is an Error, not an Exception
        try {
            throw new AssertionError("expected [5] but found [4]");
        } catch (Exception e) {
            System.out.println("Not reached");
        } catch (Error e) {
            System.out.println("AssertionError is caught only as Error/Throwable: " + e.getMessage());
        }
    }
}

