public class Main {

    static int withFinally() {
        try {
            return 1;
        } finally {
            System.out.println("finally runs even after return");
        }
    }

    static void tryFinallyOnly() {
        try {
            throw new IllegalStateException("not handled here");
        } finally {
            System.out.println("try-finally: cleanup done, exception continues to the caller");
        }
    }

    static void multipleCatch(Object value) {
        try {
            String text = (String) value;              // may throw ClassCastException
            System.out.println(text.length());         // may throw NullPointerException
        } catch (ClassCastException e) {
            System.out.println("Specific catch: ClassCastException");
        } catch (NullPointerException e) {
            System.out.println("Specific catch: NullPointerException");
        } catch (Exception e) {
            System.out.println("General catch: must come last");
        }
    }

    public static void main(String[] args) {
        System.out.println("Returned: " + withFinally());

        try {
            tryFinallyOnly();
        } catch (IllegalStateException e) {
            System.out.println("Caller caught: " + e.getMessage());
        }

        multipleCatch(42);
        multipleCatch(null);
    }
}

public class Main {

    // Unchecked custom exception
    static class InvalidBrowserException extends RuntimeException {
        InvalidBrowserException(String message) {
            super(message);
        }
    }

    // Checked custom exception that keeps the original cause
    static class TestDataException extends Exception {
        TestDataException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    static String createDriver(String browser) {
        switch (browser.toLowerCase()) {
            case "chrome":
            case "firefox":
            case "edge":
                return browser + " driver created";
            default:
                throw new InvalidBrowserException(
                        "Unsupported browser: " + browser + ". Use chrome, firefox or edge");
        }
    }

    static int readUserCount(String value) throws TestDataException {
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            throw new TestDataException("Invalid user count in test data: " + value, e);
        }
    }

    public static void main(String[] args) {
        System.out.println(createDriver("chrome"));

        try {
            createDriver("opera");
        } catch (InvalidBrowserException e) {
            System.out.println("Caught: " + e.getMessage());
        }

        try {
            readUserCount("ten");
        } catch (TestDataException e) {
            System.out.println("Caught: " + e.getMessage());
            System.out.println("Cause: " + e.getCause().getClass().getSimpleName());
        }
    }
}

