import java.util.ArrayList;
import java.util.Arrays;
import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    public static void main(String[] args) {
        List<Integer> numbers = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));

        // The problem
        try {
            for (Integer number : numbers) {
                if (number % 2 == 0) {
                    numbers.remove(number);
                }
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("Problem: ConcurrentModificationException");
        }

        // Fix 1: iterator.remove()
        List<Integer> first = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        Iterator<Integer> iterator = first.iterator();
        while (iterator.hasNext()) {
            if (iterator.next() % 2 == 0) {
                iterator.remove();
            }
        }
        System.out.println("Fix 1 iterator.remove(): " + first);

        // Fix 2: removeIf
        List<Integer> second = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        second.removeIf(number -> number % 2 == 0);
        System.out.println("Fix 2 removeIf: " + second);

        // Fix 3: loop backwards by index
        List<Integer> third = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        for (int i = third.size() - 1; i >= 0; i--) {
            if (third.get(i) % 2 == 0) {
                third.remove(i);
            }
        }
        System.out.println("Fix 3 backward loop: " + third);

        // Fix 4: concurrent collection
        List<Integer> fourth = new CopyOnWriteArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        for (Integer number : fourth) {
            if (number % 2 == 0) {
                fourth.remove(number);
            }
        }
        System.out.println("Fix 4 CopyOnWriteArrayList: " + fourth);
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.ConcurrentModificationException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    public static void main(String[] args) {
        // Fail-fast: ArrayList
        List<String> failFast = new ArrayList<>(Arrays.asList("A", "B", "C"));
        try {
            for (String item : failFast) {
                failFast.add("D");
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("Fail-fast (ArrayList): ConcurrentModificationException");
        }

        // Fail-safe: CopyOnWriteArrayList iterates over a snapshot
        List<String> failSafe = new CopyOnWriteArrayList<>(Arrays.asList("A", "B", "C"));
        int visited = 0;
        for (String item : failSafe) {
            failSafe.add(item + "-copy");
            visited++;
        }
        System.out.println("Fail-safe visited " + visited + " items; list now has " + failSafe.size());

        // ConcurrentHashMap: no exception when modified during iteration
        Map<String, Integer> map = new ConcurrentHashMap<>();
        map.put("pass", 1);
        map.put("fail", 2);
        for (String key : map.keySet()) {
            map.put("skip", 3);
        }
        System.out.println("ConcurrentHashMap size after iteration: " + map.size());
    }
}

