import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Map<String, Integer> results = new ConcurrentHashMap<>();

        // 10 threads, each recording 1000 passed tests
        Thread[] threads = new Thread[10];
        for (int t = 0; t < threads.length; t++) {
            threads[t] = new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    results.merge("PASS", 1, Integer::sum);      // atomic update
                }
            });
            threads[t].start();
        }
        for (Thread thread : threads) {
            thread.join();
        }
        System.out.println("ConcurrentHashMap total: " + results.get("PASS"));

        // Atomic 'create once' for a shared cache
        Map<String, String> cache = new ConcurrentHashMap<>();
        String first = cache.computeIfAbsent("qa.url", key -> "https://qa.example.com");
        String second = cache.computeIfAbsent("qa.url", key -> "loaded again");
        System.out.println("Cached value reused: " + first.equals(second));

        // No nulls allowed
        try {
            cache.put("key", null);
        } catch (NullPointerException e) {
            System.out.println("ConcurrentHashMap rejects null values");
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> orderIds = Arrays.asList("ORD-3", "ORD-1", "ORD-3", "ORD-2", "ORD-1", "ORD-4");

        // Remove duplicates, keep first-seen order, and report what was duplicated
        Set<String> unique = new LinkedHashSet<>();
        Set<String> duplicates = new LinkedHashSet<>();
        for (String id : orderIds) {
            if (!unique.add(id)) {          // add() returns false if already present
                duplicates.add(id);
            }
        }
        System.out.println("Unique: " + unique);
        System.out.println("Duplicates found: " + duplicates);

        // Stream alternative
        List<String> distinct = orderIds.stream().distinct().collect(Collectors.toList());
        System.out.println("Stream distinct: " + distinct);

        // Large data: one pass, constant-time checks
        List<Integer> large = new ArrayList<>();
        for (int i = 0; i < 200000; i++) {
            large.add(i % 50000);
        }
        Set<Integer> largeUnique = new LinkedHashSet<>(large);
        System.out.println("200000 records reduced to " + largeUnique.size());
    }
}

