        // 1. Static method: ClassName::staticMethod
        List<String> longNames = tools.stream().filter(Main::isLong).collect(Collectors.toList());
        System.out.println("Static method reference: " + longNames);

        // 2. Instance method of a particular object: object::method
        tools.forEach(System.out::println);

        // 3. Instance method of an arbitrary object: ClassName::instanceMethod
        List<String> upper = tools.stream().map(String::toUpperCase).collect(Collectors.toList());
        System.out.println("Instance method reference: " + upper);

        // 4. Constructor: ClassName::new
        Supplier<List<String>> listMaker = ArrayList::new;
        List<String> fresh = listMaker.get();
        fresh.add("created with ArrayList::new");
        System.out.println(fresh);

        // Same thing as a lambda and as a method reference
        Function<String, Integer> lambda = text -> Integer.parseInt(text);
        Function<String, Integer> reference = Integer::parseInt;
        System.out.println(lambda.apply("40") + reference.apply("2"));
