import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Integer> numbers = Arrays.asList(5, 3, 8, 3, 9, 5, 5, 1);

        // 1. Set.add() returns false for a value already seen
        Set<Integer> seen = new HashSet<>();
        Set<Integer> duplicates = numbers.stream()
                .filter(number -> !seen.add(number))
                .collect(Collectors.toCollection(LinkedHashSet::new));
        System.out.println("Using Set.add(): " + duplicates);

        // 2. groupingBy + counting: also gives the counts
        Map<Integer, Long> counts = numbers.stream()
                .collect(Collectors.groupingBy(Function.identity(), LinkedHashMap::new, Collectors.counting()));
        Map<Integer, Long> duplicateCounts = counts.entrySet().stream()
                .filter(entry -> entry.getValue() > 1)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, LinkedHashMap::new));
        System.out.println("Using groupingBy: " + duplicateCounts);

        // 3. Collections.frequency: simple, but O(n * n)
        Set<Integer> byFrequency = numbers.stream()
                .filter(number -> Collections.frequency(numbers, number) > 1)
                .collect(Collectors.toCollection(LinkedHashSet::new));
        System.out.println("Using frequency: " + byFrequency);
    }
}

