import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {

    static int runTest(int id) throws InterruptedException {
        Thread.sleep(200);                       // simulate a test that takes 200 ms
        return id;
    }

    public static void main(String[] args) throws Exception {
        int tests = 8;

        // One after another
        long start = System.currentTimeMillis();
        for (int i = 1; i <= tests; i++) {
            runTest(i);
        }
        long sequential = System.currentTimeMillis() - start;

        // In parallel on 4 threads
        ExecutorService pool = Executors.newFixedThreadPool(4);
        AtomicInteger completed = new AtomicInteger();
        List<Future<Integer>> futures = new ArrayList<>();

        start = System.currentTimeMillis();
        for (int i = 1; i <= tests; i++) {
            final int id = i;
            futures.add(pool.submit(() -> {
                int result = runTest(id);
                completed.incrementAndGet();     // thread-safe counter
                return result;
            }));
        }
        for (Future<Integer> future : futures) {
            future.get();                        // wait for each task
        }
        long parallel = System.currentTimeMillis() - start;
        pool.shutdown();

        System.out.println("Tests completed in parallel: " + completed.get());
        System.out.println("Parallel run was faster: " + (parallel < sequential));
    }
}

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {

    // One 'driver' per thread
    static final ThreadLocal<String> DRIVER = new ThreadLocal<>();
    static final AtomicInteger SESSION_COUNTER = new AtomicInteger();
    static final Map<String, String> RESULTS = new ConcurrentHashMap<>();

    static void setUp() {
        DRIVER.set("browser-session-" + SESSION_COUNTER.incrementAndGet());
    }

    static void tearDown() {
        DRIVER.remove();                 // prevents leaks when pool threads are reused
    }

    static void runTest(String testName) {
        setUp();
        try {
            String mySession = DRIVER.get();
            Thread.sleep(50);                               // other threads run meanwhile
            boolean stillMine = mySession.equals(DRIVER.get());
            RESULTS.put(testName, stillMine ? "PASS" : "FAIL");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            tearDown();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(5);
        for (int i = 1; i <= 20; i++) {
            final String name = "test" + i;
            pool.submit(() -> runTest(name));
        }
        pool.shutdown();
        pool.awaitTermination(30, TimeUnit.SECONDS);

        long passed = RESULTS.values().stream().filter("PASS"::equals).count();
        System.out.println("Tests run: " + RESULTS.size());
        System.out.println("Each thread kept its own session: " + (passed == 20));
        System.out.println("Sessions created: " + SESSION_COUNTER.get());
    }
}

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

public class Main {

    static class User implements Serializable {
        private static final long serialVersionUID = 1L;

        private final String name;
        private final int age;
        private final transient String password;        // not serialized

        User(String name, int age, String password) {
            this.name = name;
            this.age = age;
            this.password = password;
        }

        @Override
        public String toString() {
            return "User{name=" + name + ", age=" + age + ", password=" + password + "}";
        }
    }

    public static void main(String[] args) throws Exception {
        User original = new User("Asha", 28, "Secret@123");
        System.out.println("Original:     " + original);

        // Serialization: object -> bytes (a file stream works the same way)
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(original);
        }
        System.out.println("Serialized to bytes: " + (bytes.size() > 0));

        // Deserialization: bytes -> object
        User restored;
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            restored = (User) in.readObject();
        }
        System.out.println("Deserialized: " + restored);
        System.out.println("Same object? " + (original == restored));
    }
}

