public class Main {

    static String reversePreservingSpaces(String text) {
        char[] chars = text.toCharArray();
        int left = 0;
        int right = chars.length - 1;

        while (left < right) {
            if (chars[left] == ' ') {
                left++;
            } else if (chars[right] == ' ') {
                right--;
            } else {
                char temp = chars[left];
                chars[left] = chars[right];
                chars[right] = temp;
                left++;
                right--;
            }
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        String[] inputs = {"I am QA", "abc de", "Java Selenium Test"};
        for (String input : inputs) {
            System.out.println("[" + input + "] -> [" + reversePreservingSpaces(input) + "]");
        }
    }
}

