import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {

    static String reverseWordOrder(String text) {
        Pattern wordPattern = Pattern.compile("[A-Za-z0-9]+");

        // 1. Collect the words
        List<String> words = new ArrayList<>();
        Matcher finder = wordPattern.matcher(text);
        while (finder.find()) {
            words.add(finder.group());
        }

        // 2. Reverse their order
        Collections.reverse(words);

        // 3. Put them back; everything else stays where it was
        Matcher replacer = wordPattern.matcher(text);
        StringBuffer result = new StringBuffer();
        int index = 0;
        while (replacer.find()) {
            replacer.appendReplacement(result, words.get(index++));
        }
        replacer.appendTail(result);
        return result.toString();
    }

    public static void main(String[] args) {
        System.out.println(reverseWordOrder("Happiest Minds 2026"));
        System.out.println(reverseWordOrder("Happiest Minds, 2026!"));
        System.out.println(reverseWordOrder("Hello, World!"));
    }
}

