public class Main {

    static boolean isPalindrome(String text) {
        int left = 0;
        int right = text.length() - 1;

        while (left < right) {
            if (text.charAt(left) != text.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    // Ignores case, spaces and punctuation
    static boolean isPalindromePhrase(String text) {
        String cleaned = text.toLowerCase().replaceAll("[^a-z0-9]", "");
        return isPalindrome(cleaned);
    }

    public static void main(String[] args) {
        String[] words = {"madam", "level", "selenium", "a"};
        for (String word : words) {
            System.out.println(word + " -> " + isPalindrome(word));
        }

        String reversed = new StringBuilder("racecar").reverse().toString();
        System.out.println("racecar (reverse and compare) -> " + "racecar".equals(reversed));

        System.out.println("Madam -> " + isPalindrome("Madam") + " (case-sensitive)");
        System.out.println("A man, a plan, a canal: Panama -> " + isPalindromePhrase("A man, a plan, a canal: Panama"));
    }
}

import java.util.LinkedHashMap;
import java.util.Map;

public class Main {

    static Character[] firstAndLastUnique(String text) {
        Map<Character, Integer> counts = new LinkedHashMap<>();
        for (char ch : text.toCharArray()) {
            counts.merge(ch, 1, Integer::sum);
        }

        Character first = null;
        Character last = null;
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            if (entry.getValue() == 1) {
                if (first == null) {
                    first = entry.getKey();
                }
                last = entry.getKey();
            }
        }
        return new Character[]{first, last};
    }

    public static void main(String[] args) {
        String[] inputs = {"swiss", "automation", "aabb"};
        for (String input : inputs) {
            Character[] result = firstAndLastUnique(input);
            System.out.println(input + " -> first: " + result[0] + ", last: " + result[1]);
        }

        // Without a map: indexOf equals lastIndexOf for a character that occurs once
        String text = "swiss";
        for (char ch : text.toCharArray()) {
            if (text.indexOf(ch) == text.lastIndexOf(ch)) {
                System.out.println("indexOf approach, first: " + ch);
                break;
            }
        }
    }
}

