        String text = "mississippi";

        Map<Character, Integer> counts = new LinkedHashMap<>();
        for (char ch : text.toCharArray()) {
            if (ch != ' ') {
                counts.merge(ch, 1, Integer::sum);
            }
        }
        System.out.println("Counts: " + counts);

        char most = ' ';
        char least = ' ';
        char secondMost = ' ';
        int max = 0;
        int secondMax = 0;
        int min = Integer.MAX_VALUE;

        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            int count = entry.getValue();

            if (count > max) {
                secondMax = max;
                secondMost = most;
                max = count;
                most = entry.getKey();
            } else if (count > secondMax && count < max) {
                secondMax = count;
                secondMost = entry.getKey();
            }

            if (count < min) {
                min = count;
                least = entry.getKey();
            }
        }

        System.out.println("Most frequent: " + most + " (" + max + ")");
        System.out.println("Least frequent: " + least + " (" + min + ")");
        System.out.println("Second most repeating: " + secondMost + " (" + secondMax + ")");
    }
}

