import java.util.HashMap;
import java.util.Map;

public class Main {

    static String longestUniqueSubstring(String text) {
        Map<Character, Integer> lastSeen = new HashMap<>();
        int left = 0;
        int bestStart = 0;
        int bestLength = 0;

        for (int right = 0; right < text.length(); right++) {
            char ch = text.charAt(right);

            // Duplicate inside the current window: move the left edge past it
            if (lastSeen.containsKey(ch) && lastSeen.get(ch) >= left) {
                left = lastSeen.get(ch) + 1;
            }
            lastSeen.put(ch, right);

            if (right - left + 1 > bestLength) {
                bestLength = right - left + 1;
                bestStart = left;
            }
        }
        return text.substring(bestStart, bestStart + bestLength);
    }

    public static void main(String[] args) {
        String[] inputs = {"abcabcbb", "bbbbb", "pwwkew", "automation", "abba"};
        for (String input : inputs) {
            String longest = longestUniqueSubstring(input);
            System.out.println(input + " -> " + longest + " (length " + longest.length() + ")");
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {

    static void expand(String text, int left, int right, List<String> found) {
        while (left >= 0 && right < text.length() && text.charAt(left) == text.charAt(right)) {
            found.add(text.substring(left, right + 1));
            left--;
            right++;
        }
    }

    static List<String> palindromicSubstrings(String text) {
        List<String> found = new ArrayList<>();
        for (int centre = 0; centre < text.length(); centre++) {
            expand(text, centre, centre, found);          // odd length
            expand(text, centre, centre + 1, found);      // even length
        }
        return found;
    }

    public static void main(String[] args) {
        String[] inputs = {"abba", "aaa", "abc", "madam"};
        for (String input : inputs) {
            List<String> palindromes = palindromicSubstrings(input);
            String longest = "";
            for (String palindrome : palindromes) {
                if (palindrome.length() > longest.length()) {
                    longest = palindrome;
                }
            }
            System.out.println(input + " -> count " + palindromes.size() + " " + palindromes + ", longest: " + longest);
        }
    }
}

public class Main {

    static boolean isRotation(String first, String second) {
        if (first == null || second == null || first.length() != second.length()) {
            return false;
        }
        return (first + first).contains(second);
    }

    public static void main(String[] args) {
        System.out.println("ABCD, CDAB -> " + isRotation("ABCD", "CDAB"));
        System.out.println("ABCD, DABC -> " + isRotation("ABCD", "DABC"));
        System.out.println("ABCD, ACBD -> " + isRotation("ABCD", "ACBD"));
        System.out.println("ABCD, AB   -> " + isRotation("ABCD", "AB"));
        System.out.println("selenium, niumsele -> " + isRotation("selenium", "niumsele"));

        // Where the rotation starts
        String doubled = "ABCD" + "ABCD";
        System.out.println("CDAB found in " + doubled + " at index " + doubled.indexOf("CDAB"));
    }
}

public class Main {

    static String middle(String text) {
        if (text == null || text.isEmpty()) {
            return "";
        }
        int mid = text.length() / 2;

        if (text.length() % 2 == 0) {
            return text.substring(mid - 1, mid + 1);     // two middle characters
        }
        return text.substring(mid, mid + 1);             // one middle character
    }

    public static void main(String[] args) {
        String[] inputs = {"hello", "java", "selenium", "testing", "a", ""};
        for (String input : inputs) {
            System.out.println("[" + input + "] length " + input.length() + " -> [" + middle(input) + "]");
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class Main {

    static String transform(String text) {
        // Pass 1: count every character
        Map<Character, Integer> counts = new HashMap<>();
        for (char ch : text.toCharArray()) {
            counts.merge(ch, 1, Integer::sum);
        }

        // Pass 2: repeated characters are replaced by their count
        StringBuilder result = new StringBuilder();
        for (char ch : text.toCharArray()) {
            int count = counts.get(ch);
            if (count > 1) {
                result.append(count);
            } else {
                result.append(ch);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        System.out.println("tomorrow -> " + transform("tomorrow"));
        System.out.println("success  -> " + transform("success"));
        System.out.println("java     -> " + transform("java"));
    }
}

