        String[] a = {"abc123", "def456", "ijk789", "mno246", "uvw135"};
        String str = "Dear Candidate please join the call";

        // Part 1: vowels from the array, in sequence
        List<Character> vowels = new ArrayList<>();
        for (String element : a) {
            for (char ch : element.toCharArray()) {
                if ("aeiouAEIOU".indexOf(ch) != -1) {
                    vowels.add(ch);
                }
            }
        }
        System.out.println("Vowels in sequence: " + vowels);

        // Part 2: replace odd positions (1st, 3rd, 5th ... = indexes 0, 2, 4 ...)
        char[] chars = str.toCharArray();
        int used = 0;
        for (int index = 0; index < chars.length; index += 2) {
            chars[index] = vowels.get(used % vowels.size());
            used++;
        }

        System.out.println("Original: " + str);
        System.out.println("Result:   " + new String(chars));
        System.out.println("Characters replaced: " + used);
    }
}

