import java.util.ArrayList;
import java.util.List;

public class Main {

    static List<Integer> primesUpTo(int n) {
        boolean[] notPrime = new boolean[n + 1];
        List<Integer> primes = new ArrayList<>();

        for (int i = 2; (long) i * i <= n; i++) {
            if (!notPrime[i]) {
                for (int multiple = i * i; multiple <= n; multiple += i) {
                    notPrime[multiple] = true;
                }
            }
        }
        for (int i = 2; i <= n; i++) {
            if (!notPrime[i]) {
                primes.add(i);
            }
        }
        return primes;
    }

    public static void main(String[] args) {
        System.out.println("Primes up to 30: " + primesUpTo(30));
        System.out.println("Number of primes up to 100: " + primesUpTo(100).size());
        System.out.println("Number of primes up to 1000000: " + primesUpTo(1000000).size());
    }
}

public class Main {
    public static void main(String[] args) {
        int number = 12345;

        // Reverse first, so digits come out left to right
        int reversed = 0;
        int temp = number;
        while (temp > 0) {
            reversed = reversed * 10 + temp % 10;
            temp /= 10;
        }

        StringBuilder everyDigitTwice = new StringBuilder();
        StringBuilder evenDigitsTwice = new StringBuilder();

        while (reversed > 0) {
            int digit = reversed % 10;

            everyDigitTwice.append(digit).append(digit);

            evenDigitsTwice.append(digit);
            if (digit % 2 == 0) {
                evenDigitsTwice.append(digit);
            }
            reversed /= 10;
        }

        System.out.println("Every digit twice: " + everyDigitTwice);
        System.out.println("Even digits twice: " + evenDigitsTwice);

        // String approach: keeps zeros
        StringBuilder viaString = new StringBuilder();
        for (char ch : String.valueOf(1020).toCharArray()) {
            viaString.append(ch).append(ch);
        }
        System.out.println("1020 using a String: " + viaString);
    }
}

public class Main {

    static int sumOfDigits(int number) {
        number = Math.abs(number);
        int sum = 0;
        while (number > 0) {
            sum += number % 10;
            number /= 10;
        }
        return sum;
    }

    static int sumRecursive(int number) {
        return number == 0 ? 0 : number % 10 + sumRecursive(number / 10);
    }

    public static void main(String[] args) {
        System.out.println("123 -> " + sumOfDigits(123));
        System.out.println("9875 -> " + sumOfDigits(9875));
        System.out.println("-45 -> " + sumOfDigits(-45));
        System.out.println("Recursive 123 -> " + sumRecursive(123));

        int stringSum = 0;
        for (char ch : "123".toCharArray()) {
            stringSum += ch - '0';
        }
        System.out.println("String approach -> " + stringSum);

        int root = 9875;
        while (root > 9) {
            root = sumOfDigits(root);
        }
        System.out.println("Digital root of 9875 -> " + root);
    }
}

public class Main {

    static int maxBinaryGap(int number) {
        String binary = Integer.toBinaryString(number);
        int best = 0;
        int current = 0;

        for (char bit : binary.toCharArray()) {
            if (bit == '1') {
                best = Math.max(best, current);     // a gap is closed by a 1
                current = 0;
            } else {
                current++;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        int[] numbers = {529, 20, 8, 9, 1041};
        for (int number : numbers) {
            System.out.println(number + " = " + Integer.toBinaryString(number)
                    + " -> max gap " + maxBinaryGap(number));
        }
    }
}

