    }
}

public class Main {

    // Moves of 1 or 2 steps
    static int ways(int stairs) {
        if (stairs <= 2) {
            return Math.max(stairs, 1);
        }
        int twoBefore = 1;      // ways(1)
        int oneBefore = 2;      // ways(2)
        for (int step = 3; step <= stairs; step++) {
            int current = oneBefore + twoBefore;
            twoBefore = oneBefore;
            oneBefore = current;
        }
        return oneBefore;
    }

    // Moves of 1, 2 or 3 steps
    static int waysUpToThree(int stairs) {
        int[] table = new int[Math.max(stairs + 1, 4)];
        table[0] = 1;
        table[1] = 1;
        table[2] = 2;
        for (int step = 3; step <= stairs; step++) {
            table[step] = table[step - 1] + table[step - 2] + table[step - 3];
        }
        return table[stairs];
    }

    public static void main(String[] args) {
        System.out.println("3 stairs, 1 or 2 steps: " + ways(3));
        System.out.println("3 stairs, 1, 2 or 3 steps: " + waysUpToThree(3));
        for (int n = 1; n <= 6; n++) {
            System.out.println(n + " stairs -> " + ways(n) + " ways");
        }
    }
}

public class Main {

    static double calculate(double a, char operator, double b) {
        switch (operator) {
            case '+':
                return a + b;
            case '-':
                return a - b;
            case '*':
                return a * b;
            case '/':
                if (b == 0) {
                    throw new ArithmeticException("Cannot divide by zero");
                }
                return a / b;
            case '%':
                return a % b;
            default:
                throw new IllegalArgumentException("Unsupported operator: " + operator);
        }
    }

    static void show(double a, char operator, double b) {
        try {
            System.out.println(a + " " + operator + " " + b + " = " + calculate(a, operator, b));
        } catch (ArithmeticException | IllegalArgumentException e) {
            System.out.println(a + " " + operator + " " + b + " -> Error: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        show(12, '+', 8);
        show(12, '-', 20);
        show(2.5, '*', 4);
        show(7, '/', 2);
        show(7, '%', 2);
        show(9, '/', 0);
        show(9, '^', 2);
    }
}

public class Main {

    static int leastTime(int students, int rooms, int[] paperHours) {
        int hoursPerStudent = 0;
        for (int hours : paperHours) {              // one loop
            hoursPerStudent += hours;
        }

        int totalWork = students * hoursPerStudent;
        int roomLimit = (totalWork + rooms - 1) / rooms;     // ceiling of total / rooms

        return Math.max(roomLimit, hoursPerStudent);
    }

    public static void main(String[] args) {
        int[] papers = {3, 2, 1};      // Physics, Chemistry, Maths

        System.out.println("3 students, 2 rooms: " + leastTime(3, 2, papers) + " hours");
        System.out.println("3 students, 1 room:  " + leastTime(3, 1, papers) + " hours");
        System.out.println("3 students, 4 rooms: " + leastTime(3, 4, papers) + " hours");

        // Check the 9-hour schedule: each room is busy for exactly 9 hours
        int room1 = 3 + 3 + 3;                      // Physics for A, B, C
        int room2 = 2 + 2 + 1 + 2 + 1 + 1;          // B-Chem, C-Chem, C-Maths, A-Chem, A-Maths, B-Maths
        System.out.println("Room 1 busy: " + room1 + " h, Room 2 busy: " + room2 + " h");
    }
}

