public class Main {

    static void secondValues(int[] numbers) {
        int largest = Integer.MIN_VALUE;
        int secondLargest = Integer.MIN_VALUE;
        int smallest = Integer.MAX_VALUE;
        int secondSmallest = Integer.MAX_VALUE;

        for (int value : numbers) {
            if (value > largest) {
                secondLargest = largest;
                largest = value;
            } else if (value > secondLargest && value != largest) {
                secondLargest = value;
            }

            if (value < smallest) {
                secondSmallest = smallest;
                smallest = value;
            } else if (value < secondSmallest && value != smallest) {
                secondSmallest = value;
            }
        }

        String second = secondLargest == Integer.MIN_VALUE ? "none" : String.valueOf(secondLargest);
        String secondLow = secondSmallest == Integer.MAX_VALUE ? "none" : String.valueOf(secondSmallest);
        System.out.println("Second largest: " + second + ", second smallest: " + secondLow);
    }

    public static void main(String[] args) {
        secondValues(new int[]{10, 20, 99});
        secondValues(new int[]{14, 82, 5, 63, 82, 5});
        secondValues(new int[]{7, 7, 7});
    }
}

import java.util.Arrays;
import java.util.Collections;
import java.util.PriorityQueue;

public class Main {

    static int kthLargestWithHeap(int[] numbers, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int value : numbers) {
            minHeap.add(value);
            if (minHeap.size() > k) {
                minHeap.poll();                 // remove the smallest
            }
        }
        return minHeap.peek();
    }

    static int kthSmallestWithHeap(int[] numbers, int k) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int value : numbers) {
            maxHeap.add(value);
            if (maxHeap.size() > k) {
                maxHeap.poll();                 // remove the largest
            }
        }
        return maxHeap.peek();
    }

    public static void main(String[] args) {
        int[] numbers = {7, 10, 4, 3, 20, 15};
        int k = 3;

        int[] sorted = numbers.clone();
        Arrays.sort(sorted);
        System.out.println("Sorted: " + Arrays.toString(sorted));
        System.out.println("Sorting -> " + k + "rd smallest: " + sorted[k - 1]
                + ", " + k + "rd largest: " + sorted[sorted.length - k]);

        System.out.println("Heap -> " + k + "rd smallest: " + kthSmallestWithHeap(numbers, k)
                + ", " + k + "rd largest: " + kthLargestWithHeap(numbers, k));
    }
}

import java.util.Arrays;

public class Main {

    static void reverse(int[] numbers) {
        int left = 0;
        int right = numbers.length - 1;

        while (left < right) {
            int temp = numbers[left];
            numbers[left] = numbers[right];
            numbers[right] = temp;
            left++;
            right--;
        }
    }

    public static void main(String[] args) {
        int[] odd = {1, 2, 3, 4, 5};
        reverse(odd);
        System.out.println(Arrays.toString(odd));

        int[] even = {10, 20, 30, 40};
        reverse(even);
        System.out.println(Arrays.toString(even));

        int[] single = {7};
        reverse(single);
        System.out.println(Arrays.toString(single));
    }
}

