public class Main {

    static int findBoundary(int[] sorted, int target, boolean findFirst) {
        int low = 0;
        int high = sorted.length - 1;
        int result = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (sorted[mid] == target) {
                result = mid;                   // remember it and keep searching
                if (findFirst) {
                    high = mid - 1;             // look further left
                } else {
                    low = mid + 1;              // look further right
                }
            } else if (sorted[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[] sorted = {1, 3, 3, 4, 5, 6, 6, 6, 8, 9};

        for (int target : new int[]{6, 3, 9, 2}) {
            int first = findBoundary(sorted, target, true);
            int last = findBoundary(sorted, target, false);
            int count = first == -1 ? 0 : last - first + 1;
            System.out.println(target + " -> first: " + first + ", last: " + last + ", count: " + count);
        }
    }
}

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.StringJoiner;

public class Main {
    public static void main(String[] args) {
        int[] numbers = {1, 2, 2, 3, 4, 4, 4};

        // Map approach: O(n)
        Map<Integer, Integer> frequency = new LinkedHashMap<>();
        for (int value : numbers) {
            frequency.merge(value, 1, Integer::sum);
        }
        StringJoiner output = new StringJoiner(", ");
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            output.add(entry.getKey() + ": " + entry.getValue());
        }
        System.out.println("Map: " + output);

        // Without a map: visited array, O(n * n)
        boolean[] visited = new boolean[numbers.length];
        StringJoiner manual = new StringJoiner(", ");
        for (int i = 0; i < numbers.length; i++) {
            if (visited[i]) {
                continue;
            }
            int count = 1;
            for (int j = i + 1; j < numbers.length; j++) {
                if (numbers[i] == numbers[j]) {
                    count++;
                    visited[j] = true;
                }
            }
            manual.add(numbers[i] + ": " + count);
        }
        System.out.println("Visited array: " + manual);
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;

public class Main {

    static List<Integer> topKFrequent(int[] numbers, int k) {
        // Stage 1: count
        Map<Integer, Integer> counts = new HashMap<>();
        for (int value : numbers) {
            counts.merge(value, 1, Integer::sum);
        }

        // Stage 2: min-heap of size k, ordered by count (then by value for stable ties)
        PriorityQueue<Map.Entry<Integer, Integer>> heap = new PriorityQueue<>((a, b) -> {
            int byCount = Integer.compare(a.getValue(), b.getValue());
            return byCount != 0 ? byCount : Integer.compare(b.getKey(), a.getKey());
        });

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            heap.add(entry);
            if (heap.size() > k) {
                heap.poll();                    // drop the least frequent
            }
        }

        List<Integer> result = new ArrayList<>();
        while (!heap.isEmpty()) {
            result.add(0, heap.poll().getKey());   // most frequent first
        }
        return result;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 1, 1, 2, 2, 3, 4, 4, 4, 4, 5};

        System.out.println("Top 2: " + topKFrequent(numbers, 2));
        System.out.println("Top 3: " + topKFrequent(numbers, 3));
        System.out.println("Top 1: " + topKFrequent(new int[]{7, 7, 8}, 1));
    }
}

import java.util.Arrays;

public class Main {

    static void reverse(int[] numbers, int start, int end) {
        while (start < end) {
            int temp = numbers[start];
            numbers[start++] = numbers[end];
            numbers[end--] = temp;
        }
    }

    // In place: reverse all, reverse first k, reverse the rest
    static void rotateRight(int[] numbers, int k) {
        int n = numbers.length;
        if (n == 0) {
            return;
        }
        k = k % n;
        reverse(numbers, 0, n - 1);
        reverse(numbers, 0, k - 1);
        reverse(numbers, k, n - 1);
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        rotateRight(numbers, 2);
        System.out.println("Rotate by 2: " + Arrays.toString(numbers));

        int[] large = {1, 2, 3, 4, 5};
        rotateRight(large, 7);                  // 7 % 5 = 2
        System.out.println("Rotate by 7: " + Arrays.toString(large));

        // Extra-array version
        int[] source = {1, 2, 3, 4, 5};
        int[] result = new int[source.length];
        for (int i = 0; i < source.length; i++) {
            result[(i + 3) % source.length] = source[i];
        }
        System.out.println("Rotate by 3 (extra array): " + Arrays.toString(result));
    }
}

public class Main {

    static boolean isPalindrome(int[] numbers) {
        int left = 0;
        int right = numbers.length - 1;

        while (left < right) {
            if (numbers[left] != numbers[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("[1, 2, 3, 2, 1] -> " + isPalindrome(new int[]{1, 2, 3, 2, 1}));
        System.out.println("[1, 2, 2, 1] -> " + isPalindrome(new int[]{1, 2, 2, 1}));
        System.out.println("[1, 2, 3, 4] -> " + isPalindrome(new int[]{1, 2, 3, 4}));
        System.out.println("[7] -> " + isPalindrome(new int[]{7}));
        System.out.println("[] -> " + isPalindrome(new int[]{}));
    }
}

import java.util.Arrays;

public class Main {

    static int[] merge(int[] first, int[] second) {
        int[] result = new int[first.length + second.length];

        for (int i = 0; i < first.length; i++) {
            result[i] = first[i];
        }
        for (int j = 0; j < second.length; j++) {
            result[first.length + j] = second[j];
        }
        return result;
    }

    // Both inputs sorted: result stays sorted
    static int[] mergeSorted(int[] first, int[] second) {
        int[] result = new int[first.length + second.length];
        int i = 0, j = 0, k = 0;

        while (i < first.length && j < second.length) {
            result[k++] = first[i] <= second[j] ? first[i++] : second[j++];
        }
        while (i < first.length) {
            result[k++] = first[i++];
        }
        while (j < second.length) {
            result[k++] = second[j++];
        }
        return result;
    }

    public static void main(String[] args) {
        int[] a = {5, 1, 9};
        int[] b = {4, 8};
        System.out.println("Merged: " + Arrays.toString(merge(a, b)));

        int[] copy = new int[a.length + b.length];
        System.arraycopy(a, 0, copy, 0, a.length);
        System.arraycopy(b, 0, copy, a.length, b.length);
        System.out.println("System.arraycopy: " + Arrays.toString(copy));

        System.out.println("Merged sorted: " + Arrays.toString(mergeSorted(new int[]{1, 4, 7}, new int[]{2, 3, 8, 9})));
    }
}

