import java.util.Arrays;

public class Main {

    // Nested loops: O(n * n), no extra data structure
    static void printDuplicates(String[] items) {
        StringBuilder found = new StringBuilder();

        for (int i = 0; i < items.length; i++) {
            boolean seenBefore = false;
            for (int k = 0; k < i; k++) {
                if (items[k].equals(items[i])) {
                    seenBefore = true;
                    break;
                }
            }
            if (seenBefore) {
                continue;                       // already handled at its first position
            }
            for (int j = i + 1; j < items.length; j++) {
                if (items[i].equals(items[j])) {
                    found.append(items[i]).append(" ");
                    break;
                }
            }
        }
        System.out.println("Duplicate strings: " + found.toString().trim());
    }

    // Sort first: equal values become neighbours
    static void printDuplicatesSorted(int[] numbers) {
        int[] sorted = numbers.clone();
        Arrays.sort(sorted);
        StringBuilder found = new StringBuilder();

        for (int i = 1; i < sorted.length; i++) {
            boolean sameAsPrevious = sorted[i] == sorted[i - 1];
            boolean alreadyReported = i > 1 && sorted[i] == sorted[i - 2];
            if (sameAsPrevious && !alreadyReported) {
                found.append(sorted[i]).append(" ");
            }
        }
        System.out.println("Duplicate numbers: " + found.toString().trim());
    }

    public static void main(String[] args) {
        printDuplicates(new String[]{"java", "selenium", "java", "testng", "selenium", "java"});
        printDuplicatesSorted(new int[]{4, 2, 7, 2, 9, 4, 4, 1});
    }
}

import java.util.Arrays;

public class Main {

    static void sortZeroOneTwo(int[] numbers) {
        int low = 0;
        int mid = 0;
        int high = numbers.length - 1;

        while (mid <= high) {
            if (numbers[mid] == 0) {
                int temp = numbers[low];
                numbers[low] = numbers[mid];
                numbers[mid] = temp;
                low++;
                mid++;
            } else if (numbers[mid] == 1) {
                mid++;
            } else {
                int temp = numbers[mid];
                numbers[mid] = numbers[high];
                numbers[high] = temp;
                high--;                         // do not advance mid here
            }
        }
    }

    public static void main(String[] args) {
        int[] first = {2, 0, 1, 2, 1, 0};
        sortZeroOneTwo(first);
        System.out.println(Arrays.toString(first));

        int[] second = {0, 1, 2, 0, 1, 2, 2, 0, 1, 0};
        sortZeroOneTwo(second);
        System.out.println(Arrays.toString(second));

        int[] third = {2, 2, 1};
        sortZeroOneTwo(third);
        System.out.println(Arrays.toString(third));
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Main {

    // One pass with a HashMap: O(n)
    static int[] twoSum(int[] numbers, int target) {
        Map<Integer, Integer> indexByValue = new HashMap<>();

        for (int i = 0; i < numbers.length; i++) {
            int complement = target - numbers[i];

            if (indexByValue.containsKey(complement)) {
                return new int[]{indexByValue.get(complement), i};
            }
            indexByValue.put(numbers[i], i);
        }
        return new int[]{-1, -1};
    }

    // Brute force: O(n * n)
    static int[] twoSumBruteForce(int[] numbers, int target) {
        for (int i = 0; i < numbers.length; i++) {
            for (int j = i + 1; j < numbers.length; j++) {
                if (numbers[i] + numbers[j] == target) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{-1, -1};
    }

    public static void main(String[] args) {
        int[] numbers = {6, 8, 11, 6, 7, 18};
        int target = 17;

        int[] result = twoSum(numbers, target);
        System.out.println("HashMap: indices " + Arrays.toString(result)
                + " -> " + numbers[result[0]] + " + " + numbers[result[1]] + " = " + target);

        System.out.println("Brute force: indices " + Arrays.toString(twoSumBruteForce(numbers, target)));
        System.out.println("No pair for 100: " + Arrays.toString(twoSum(numbers, 100)));
    }
}

import java.util.Arrays;

public class Main {

    static void maxSubarray(int[] numbers) {
        int currentSum = numbers[0];
        int maxSum = numbers[0];
        int currentStart = 0;
        int bestStart = 0;
        int bestEnd = 0;

        for (int i = 1; i < numbers.length; i++) {
            if (numbers[i] > currentSum + numbers[i]) {
                currentSum = numbers[i];            // start a new subarray here
                currentStart = i;
            } else {
                currentSum += numbers[i];           // extend the current subarray
            }

            if (currentSum > maxSum) {
                maxSum = currentSum;
                bestStart = currentStart;
                bestEnd = i;
            }
        }

        System.out.println(Arrays.toString(numbers) + " -> sum " + maxSum + ", subarray "
                + Arrays.toString(Arrays.copyOfRange(numbers, bestStart, bestEnd + 1)));
    }

    public static void main(String[] args) {
        maxSubarray(new int[]{-2, 1, -3, 4, -1, 2, 1, -5, 4});
        maxSubarray(new int[]{5, 4, -1, 7, 8});
        maxSubarray(new int[]{-3, -1, -4});
    }
}

public class Main {

    static int maxProfit(int[] present, int[] future, int budget) {
        int[] dp = new int[budget + 1];         // dp[b] = best profit with budget b

        for (int i = 0; i < present.length; i++) {
            int cost = present[i];
            int profit = future[i] - present[i];

            if (profit <= 0) {
                continue;                       // never buy a stock that loses money
            }
            for (int b = budget; b >= cost; b--) {      // downward: each stock used once
                dp[b] = Math.max(dp[b], dp[b - cost] + profit);
            }
        }
        return dp[budget];
    }

    public static void main(String[] args) {
        int[] present = {5, 4, 6, 2, 3};
        int[] future = {8, 5, 4, 3, 5};

        System.out.println("Budget 10 -> maximum profit " + maxProfit(present, future, 10));
        System.out.println("Budget 5  -> maximum profit " + maxProfit(present, future, 5));
        System.out.println("Budget 1  -> maximum profit " + maxProfit(present, future, 1));

        // The choice for budget 10: indexes 0, 3 and 4
        int cost = present[0] + present[3] + present[4];
        int sale = future[0] + future[3] + future[4];
        System.out.println("Buy for " + cost + ", sell for " + sale + ", profit " + (sale - cost));
    }
}

import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> departments = new HashMap<>();
        departments.put("QA", 12);
        departments.put("Dev", 30);
        departments.put(null, 3);
        departments.put("Ops", 7);
        departments.put("BA", 5);

        // The problem: natural ordering cannot compare null
        try {
            new TreeMap<>(departments);
        } catch (NullPointerException e) {
            System.out.println("new TreeMap<>(map) fails: NullPointerException");
        }

        // Fix 1: TreeMap with a null-friendly comparator
        Map<String, Integer> nullFirst = new TreeMap<>(Comparator.nullsFirst(Comparator.naturalOrder()));
        nullFirst.putAll(departments);
        System.out.println("nullsFirst: " + nullFirst);

        Map<String, Integer> nullLast = new TreeMap<>(Comparator.nullsLast(Comparator.naturalOrder()));
        nullLast.putAll(departments);
        System.out.println("nullsLast:  " + nullLast);

        // Fix 2: stream sorted by key into a LinkedHashMap
        Map<String, Integer> viaStream = departments.entrySet().stream()
                .sorted(Map.Entry.comparingByKey(Comparator.nullsFirst(Comparator.naturalOrder())))
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, LinkedHashMap::new));
        System.out.println("Stream:     " + viaStream);
    }
}

