public class Main {

    static class Node {
        int value;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    static Node reverse(Node head) {
        Node previous = null;
        Node current = head;

        while (current != null) {
            Node next = current.next;       // 1. save the rest of the list
            current.next = previous;        // 2. turn the link around
            previous = current;             // 3. move previous forward
            current = next;                 // 4. move current forward
        }
        return previous;                    // new head
    }

    static Node reverseRecursive(Node head) {
        if (head == null || head.next == null) {
            return head;
        }
        Node newHead = reverseRecursive(head.next);
        head.next.next = head;
        head.next = null;
        return newHead;
    }

    static String describe(Node head) {
        StringBuilder text = new StringBuilder();
        for (Node node = head; node != null; node = node.next) {
            text.append(node.value).append(node.next != null ? " -> " : "");
        }
        return text.toString();
    }

    public static void main(String[] args) {
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);

        System.out.println("Original:  " + describe(head));

        Node reversed = reverse(head);
        System.out.println("Reversed:  " + describe(reversed));

        Node back = reverseRecursive(reversed);
        System.out.println("Recursive: " + describe(back));
    }
}

public class Main {

    static class Node {
        int value;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    static boolean hasCycle(Node head) {
        Node slow = head;
        Node fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;               // one step
            fast = fast.next.next;          // two steps
            if (slow == fast) {
                return true;                // they met: cycle
            }
        }
        return false;                       // fast reached the end: no cycle
    }

    static Integer cycleStart(Node head) {
        Node slow = head;
        Node fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                slow = head;
                while (slow != fast) {
                    slow = slow.next;
                    fast = fast.next;
                }
                return slow.value;
            }
        }
        return null;
    }

    public static void main(String[] args) {
        Node head = new Node(1);
        Node second = new Node(2);
        Node third = new Node(3);
        Node fourth = new Node(4);
        Node fifth = new Node(5);
        head.next = second;
        second.next = third;
        third.next = fourth;
        fourth.next = fifth;

        System.out.println("Without a cycle: " + hasCycle(head));

        fifth.next = third;                 // create the cycle 5 -> 3
        System.out.println("With a cycle: " + hasCycle(head));
        System.out.println("Cycle starts at node: " + cycleStart(head));
    }
}

