import functools
import time


def log_time(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)          # call the original function
        print(f"{func.__name__} finished in {time.time() - start:.2f}s")
        return result
    return wrapper


def retry(times):                               # decorator with an argument
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as error:
                    print(f"Attempt {attempt} failed: {error}")
            raise RuntimeError(f"{func.__name__} failed after {times} attempts")
        return wrapper
    return decorator


@log_time
def load_page(name):
    time.sleep(0.1)
    return f"{name} loaded"


